import{z as o,x as B,o as A,c as p,q as r,j as s,D as e,d as l,s as n,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"缓冲池 LRU-K / 2Q","description":"","frontmatter":{"title":"缓冲池 LRU-K / 2Q","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/buffer-pool-lru-k.md","filePath":"cs/buffer-pool-lru-k.md","lastUpdated":1791063341000}'),d={name:"cs/buffer-pool-lru-k.md"};function C(h,a,m,u,f,D){const t=B("Mermaid");return A(),p("div",null,[a[2]||(a[2]=r('<h1 id="缓冲池-lru-k-2q" tabindex="-1">缓冲池 LRU-K / 2Q <a class="header-anchor" href="#缓冲池-lru-k-2q" aria-label="Permalink to &quot;缓冲池 LRU-K / 2Q&quot;">​</a></h1><div class="epigraph"><p>一次扫描污染 LRU：顺序页只有一次命中却把热点挤出。LRU-K 看第 K 次最近访问时间，2Q 把第一次与多次访问分队列。</p><footer>—— 据 O&#39;Neil, O&#39;Neil and Weikum, LRU-K, SIGMOD 1993；Johnson and Shasha, 2Q；Gray and Reuter</footer></div><p>执行引擎在<a href="/cs/late-materialization">延迟物化</a>封口，gather 会打页。本课打开存储进阶：主干缓冲与脏页在 WAL 前已承认池的存在，替换策略往往一笔带过。缺口是扫描污染与「相关引用」：经典 LRU 把刚扫过的一次性页当成热点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>OLTP 热点页应常驻；OLAP 大扫描应走过去几乎不留。LRU 把最近触摸的页放头，扫描让池充满一次性页，随后点查全 miss。缺口是<strong>用访问历史区分扫描与循环热点</strong>，不是再定义页。</p><p>LRU-K：记录每页最近 K 次访问时间，替换「第 K 次访问最久远」的页（K=2 常用）。一次扫描只有一次访问，第 2 次时间是 \\(-\\infty\\)，优先被换。2Q：A1 队列收第一次入池页，很快淘汰；第二次命中晋升到 Am（常 LRU）。时钟算法是近似，本课点名。</p><p><span class="marginnote">O&#39;Neil, O&#39;Neil, Weikum，SIGMOD 1993。Johnson and Shasha 2Q。与操作系统页替换同构，但数据库知道扫描、预取、脏页刷盘约束，不能直接套 OS LRU。</span></p><p><span class="marginnote">数字实例：池只有 4 帧，热点页 A、B 交替访问，随后来一次 4 页的顺序扫描 S1..S4。朴素 LRU 扫完后会把 A、B 全部挤出——下一次点查全 miss；LRU-K（K=2）记得 S1..S4 都只有一次访问（第 2 次时间是负无穷），被换的是扫描页自己，热点保住。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>池：固定帧，每帧一页（或更大块）。命中：更新该页历史。未命中：按策略选牺牲者；若脏则先写（与 steal 策略、WAL 的 pageLSN 一致）。pin 下一课：正在用的页不能换。</p><p>预取：顺序扫描可提前读，策略应避免预取页立刻升成热点。中间结果临时页可标快速逐出。</p>',11)),(A(),s(i,null,{default:e(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E8%AE%BF%E9%97%AE%E9%A1%B5%22%5D%20--%3E%20K%5B%22%E6%9B%B4%E6%96%B0%E6%9C%80%E8%BF%91%20K%20%E6%AC%A1%E6%97%B6%E9%97%B4%22%5D%0A%20%20K%20--%3E%20VIC%5B%22%E7%89%BA%E7%89%B2%E7%AC%AC%20K%20%E6%AC%A1%E6%9C%80%E6%97%A7%22%5D%0A%20%20SCAN%5B%22%E9%A1%BA%E5%BA%8F%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20ONCE%5B%22%E5%8F%AA%E6%9C%89%E4%B8%80%E6%AC%A1%E8%AE%BF%E9%97%AE%22%5D%0A%20%20ONCE%20--%3E%20OUT%5B%22%E4%BC%98%E5%85%88%E6%8D%A2%E5%87%BA%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"代价模型假设的缓存命中率来自这套策略。校准若假定命中、策略却被扫描污染，DP 会错。并行工人争同一池，latch 保护替换结构——再下一课 latch。",-1)),a[5]||(a[5]=E("p",null,"脏页写回：替换要写，延长 miss 路径；后台刷脏与检查点互动，恢复课再接。",-1)),a[6]||(a[6]=E("p",null,"下图回答一个具体问题：2Q 里一页从入池到淘汰，在两条队列间如何流动。",-1)),(A(),s(i,null,{default:e(()=>[n(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20MISS%5B%22%E6%9C%AA%E5%91%BD%E4%B8%AD%EF%BC%9A%E6%96%B0%E9%A1%B5%E5%85%A5%E6%B1%A0%22%5D%20--%3E%20A1%5B%22A1%20%E9%98%9F%E5%88%97%EF%BC%9A%E5%8F%AA%E8%A2%AB%E8%AE%BF%E9%97%AE%E8%BF%87%E4%B8%80%E6%AC%A1%22%5D%0A%20%20A1%20--%3E%7C%22%E9%98%9F%E5%88%97%E7%9F%AD%E3%80%81%E7%BF%BB%E5%8F%B0%E5%BF%AB%22%7C%20OUT%5B%22%E7%9B%B4%E6%8E%A5%E6%B7%98%E6%B1%B0%EF%BC%8C%E4%B8%8D%E8%BF%9B%E7%83%AD%E7%82%B9%E5%8C%BA%22%5D%0A%20%20A1%20--%3E%7C%22%E7%AC%AC%E4%BA%8C%E6%AC%A1%E5%91%BD%E4%B8%AD%22%7C%20AM%5B%22Am%20%E9%98%9F%E5%88%97%EF%BC%9A%E7%A1%AE%E8%AE%A4%E7%9A%84%E7%83%AD%E7%82%B9%EF%BC%88LRU%EF%BC%89%22%5D%0A%20%20AM%20--%3E%7C%22%E5%86%8D%E6%AC%A1%E5%91%BD%E4%B8%AD%22%7C%20AM%0A%20%20AM%20--%3E%7C%22%E9%95%BF%E6%9C%9F%E6%97%A0%E4%BA%BA%E8%AE%BF%E9%97%AE%22%7C%20EV%5B%22%E6%9C%80%E7%BB%88%E8%A2%AB%E6%B7%98%E6%B1%B0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">直觉类比：2Q 像健身房试课制——新客（第一次入池的页）先进体验区 A1，体验区小、翻台快；第二次来才转正进会员区 Am。一次性访客成群涌入也只挤占体验区，正式会员不受影响，这就是「抗扫描污染」的直觉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 pin 计数与 latch 区别。也不把 OS page cache 与库缓冲池双缓存当推荐——库常用 <code>O_DIRECT</code>。LRU-K 的历史表本身占内存，K 与精度是调参。</p><p>后课默认：替换要抗扫描污染；热点靠第二次及以后访问识别。pin 与 latch：页被固定时不能成牺牲者，并发要用短锁。</p><p>策略服务的是命中率，不服务可串行。</p><p><span class="marginnote">常见误区：初学者以为 LRU-K 「更聪明所以一定更快」。历史表本身占内存，每次命中要更新 K 个时间戳；K=1 退化为朴素 LRU，K 太大又对新热点反应迟钝。K=2 是文献里的常用折中——参数是拿来调的，不是免费午餐。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LRU-K / 2Q 区分一次性扫描与多次热点。</li><li>脏牺牲者先写；正在使用的页必须 pin。</li><li>pin 与 latch 下一课：固定与互斥不是同一把锁。</li><li>出处：O&#39;Neil et al. LRU-K；Johnson and Shasha 2Q；Gray and Reuter。</li></ul>',8))])}const F=o(d,[["render",C]]);export{L as __pageData,F as default};
